(613672, 63142, 772, '<td valign="top">This is excellent work.  I love the smooth curve and the abstract reflection in the glass.  I also find a high level of interest in your integration of modern science (SEI and the architecture itself) with the church.  That bit of contrast is quite striking for me.  Excellent exposure... - best of show</td>', 'This is excellent work.  I love the smooth curve and the abstract reflection in the glass.  I also find a high level of interest in your integration of modern science (SEI and the architecture itself) with the church.  That bit of contrast is quite striking for me.  Excellent exposure... - best of show', '2004-03-08 09:47:20.000000', NULL, 1),
(613673, 63599, 16850, '<td valign="top">Tough exposure situation. Too much info for me, perhaps an interseting portion.</td>', 'Tough exposure situation. Too much info for me, perhaps an interseting portion.', '2004-03-08 09:47:27.000000', NULL, 1),
(613678, 63573, 16850, '<td valign="top">Nice. The clouds didn''t do you any favor though. Would it have been possible to take this in the left lane for more symmetry?</td>', 'Nice. The clouds didn''t do you any favor though. Would it have been possible to take this in the left lane for more symmetry?', '2004-03-08 09:51:25.000000', NULL, 1),
(613681, 62907, 16850, '<td valign="top">Where are the nickles?</td>', 'Where are the nickles?', '2004-03-08 09:52:30.000000', NULL, 1),
(613682, 63718, 16850, '<td valign="top">Well done.</td>', 'Well done.', '2004-03-08 09:53:23.000000', NULL, 1),
