(613689, 63336, 16850, '<td valign="top">I can appreciate it. I understand the logo is enough, but I bet the client would want to read ''BMW''.</td>', 'I can appreciate it. I understand the logo is enough, but I bet the client would want to read ''BMW''.', '2004-03-08 10:01:40.000000', NULL, 1),
(613691, 62924, 16850, '<td valign="top">Nice composition and color choice.</td>', 'Nice composition and color choice.', '2004-03-08 10:05:45.000000', NULL, 1),
(613692, 63605, 16850, '<td valign="top">Nice fingerprint!</td>', 'Nice fingerprint!', '2004-03-08 10:06:12.000000', NULL, 1),
(613695, 63371, 16850, '<td valign="top">Very nicely done.</td>', 'Very nicely done.', '2004-03-08 10:07:41.000000', NULL, 1),
(613696, 63435, 17037, '<td valign="top">Nicely done!<br/></td>', 'Nicely done!', '2004-03-08 10:10:02.000000', NULL, 1),
(613697, 63495, 16850, '<td valign="top">Nice use of framming. Left crop needs more or less, stopping at a feature edge usually dosn''t work.</td>', 'Nice use of framming. Left crop needs more or less, stopping at a feature edge usually dosn''t work.', '2004-03-08 10:10:06.000000', NULL, 1),
