(613700, 63677, 16850, '<td valign="top">Say that 10 times, fast.</td>', 'Say that 10 times, fast.', '2004-03-08 10:10:39.000000', NULL, 1),
(613702, 63475, 16850, '<td valign="top">Oohhh... really like this.</td>', 'Oohhh... really like this.', '2004-03-08 10:11:53.000000', NULL, 1),
(613703, 63715, 17037, '<td valign="top">Sorry I can''t tell what it is!</td>', 'Sorry I can''t tell what it is!', '2004-03-08 10:11:56.000000', NULL, 1),
(613704, 63454, 17037, '<td valign="top">Too confusing</td>', 'Too confusing', '2004-03-08 10:12:09.000000', NULL, 1),
(613705, 63635, 17037, '<td valign="top">Nicely done</td>', 'Nicely done', '2004-03-08 10:12:45.000000', NULL, 1),
(613706, 63565, 9073, '<td valign="top">We have structural integrity, but do we have much photographic integrity? I''m sorry to say that I can''t see anything but a jumble of lines intersperced with light dabbles. Maybe this would have worked better if a strong line had been chosen.</td>', 'We have structural integrity, but do we have much photographic integrity? I''m sorry to say that I can''t see anything but a jumble of lines intersperced with light dabbles. Maybe this would have worked better if a strong line had been chosen.', '2004-03-08 10:12:51.000000', NULL, 1),
(613707, 63580, 17037, '<td valign="top">Too dark</td>', 'Too dark', '2004-03-08 10:12:58.000000', NULL, 1);
