(613813, 63371, 17037, '<td valign="top">Excellent</td>', 'Excellent', '2004-03-08 10:35:44.000000', NULL, 1),
(613817, 63186, 327, '<td valign="top">? I don''t see a sign here. These are the type of roads I hunt for riding my motorcycley. Looks like a good one.  I think you need a bit of saturation here to perk up the colors. The focus is real nice. The light is a bit bright here and there.</td>', '? I don''t see a sign here. These are the type of roads I hunt for riding my motorcycley. Looks like a good one.  I think you need a bit of saturation here to perk up the colors. The focus is real nice. The light is a bit bright here and there.', '2004-03-08 10:36:19.000000', NULL, 1),
(613819, 63394, 9821, '<td valign="top">looks like it''s under water ... i like it a lot ... great colors</td>', 'looks like it''s under water ... i like it a lot ... great colors', '2004-03-08 10:36:43.000000', NULL, 1),
(613822, 63644, 9821, '<td valign="top">nice</td>', 'nice', '2004-03-08 10:37:06.000000', NULL, 1),
(613825, 63609, 5792, '<td valign="top">Clone out the annoying pole in front of the church door here to improve this fine composition. That makes a big difference with this image. The wide angle view works well here.</td>', 'Clone out the annoying pole in front of the church door here to improve this fine composition. That makes a big difference with this image. The wide angle view works well here.', '2004-03-08 10:37:44.000000', NULL, 1),
(613827, 63238, 327, '<td valign="top">Sure now it''s really going to rain!! Neat idea for the challenge.</td>', 'Sure now it''s really going to rain!! Neat idea for the challenge.', '2004-03-08 10:38:00.000000', NULL, 1),
(613829, 63662, 327, '<td valign="top">:) I thought of this same thing for the challenge, but couldn''t get close to one. Not a bad entry. That darn fence!</td>', ':) I thought of this same thing for the challenge, but couldn''t get close to one. Not a bad entry. That darn fence!', '2004-03-08 10:38:42.000000', NULL, 1),
(613830, 63405, 327, '<td valign="top">Pretty water falls. Good shooting.</td>', 'Pretty water falls. Good shooting.', '2004-03-08 10:39:09.000000', NULL, 1),
