(614488, 62924, 16316, '<td valign="top">Something happening near the watch stem in the black; part of post processing?<br/>Anyway I like the "blue steel" and clarity of the movements and jewels. Nice macro.</td>', 'Something happening near the watch stem in the black; part of post processing?Anyway I like the "blue steel" and clarity of the movements and jewels. Nice macro.', '2004-03-08 19:40:01.000000', NULL, 1),
(614489, 63215, 14476, '<td valign="top">Pretty terrific geometry you found here.  Composition is right on and color, of course, is excellent.  It''s a 10.</td>', 'Pretty terrific geometry you found here.  Composition is right on and color, of course, is excellent.  It''s a 10.', '2004-03-08 19:40:44.000000', NULL, 1),
(614491, 63717, 16316, '<td valign="top">This works very nicely in gray scale. Only comment is that if the main arch seems slightly out of focus compared with the rest of the image. May be just the lighting though. Nice.</td>', 'This works very nicely in gray scale. Only comment is that if the main arch seems slightly out of focus compared with the rest of the image. May be just the lighting though. Nice.', '2004-03-08 19:41:42.000000', NULL, 1),
(614492, 63393, 14476, '<td valign="top">This is a super design.  Colors harmonize and the blue accent is just where it belongs.  Good seeing.  Good focus which may have been difficult as this looks like an overhead shot.</td>', 'This is a super design.  Colors harmonize and the blue accent is just where it belongs.  Good seeing.  Good focus which may have been difficult as this looks like an overhead shot.', '2004-03-08 19:43:17.000000', NULL, 1),
