INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(614553, 63142, 7810, '<td valign="top">like the duotone. Creative take on the challenge  nice shot</td>', 'like the duotone. Creative take on the challenge  nice shot', '2004-03-08 21:23:36.000000', NULL, 1),
(614554, 63724, 15407, '<td valign="top">Hey I have one exactly like that!  It''s a classic.  The excellent design &amp; engineering by HONDA on this machine &amp; its predecessors helped to make inroads into the American motorcycle market.  The unusual perspective you used and your approach to capturing the essence of the design by placing the Trail 90 in its ''element'' add a lot to the picture IMHO.  The exclusion of the handlebar also added value to the picture as it likely would have broken the flow of the lines in your composure.  The colors are correct &amp; it looks as though you had some additional lighting as there are no obvious flash hot spots in a picture that was taken under a canopy of trees.  <br/></td>', 'Hey I have one exactly like that!  It''s a classic.  The excellent design & engineering by HONDA on this machine & its predecessors helped to make inroads into the American motorcycle market.  The unusual perspective you used and your approach to capturing the essence of the design by placing the Trail 90 in its ''element'' add a lot to the picture IMHO.  The exclusion of the handlebar also added value to the picture as it likely would have broken the flow of the lines in your composure.  The colors are correct & it looks as though you had some additional lighting as there are no obvious flash hot spots in a picture that was taken under a canopy of trees.  ', '2004-03-08 21:24:08.000000', NULL, 1),
(614555, 62907, 7810, '<td valign="top">Ah sweet memories...love the b&amp;W nice shot for the challenge</td>', 'Ah sweet memories...love the b&W nice shot for the challenge', '2004-03-08 21:24:21.000000', NULL, 1),
