(617891, 63683, 6888, '<td valign="top">meets the challenge, but not an overly interesting photo</td>', 'meets the challenge, but not an overly interesting photo', '2004-03-11 09:55:10.000000', NULL, 1),
(617894, 63215, 6888, '<td valign="top">There is something with the building on the right that is just not right.  It looks like just a sliver of building sitting there, and that unfortunately is very distracting</td>', 'There is something with the building on the right that is just not right.  It looks like just a sliver of building sitting there, and that unfortunately is very distracting', '2004-03-11 09:56:21.000000', NULL, 1),
(618018, 63528, 6008, '<td valign="top">This almost looks like an illusion as although my brain is telling me that they are both facing toward me my eyes are thinking they are both facing/opening away from me too. Very trippy! As for the image itself, I like it. The yellow cast works well to age up the image and I like the ''dirty'' clock face. Looking at it more it looks like a clock instead of my initial thought of a pocketwatch, which explains the ''column'' at the back that seemed a little distracting.</td>', 'This almost looks like an illusion as although my brain is telling me that they are both facing toward me my eyes are thinking they are both facing/opening away from me too. Very trippy! As for the image itself, I like it. The yellow cast works well to age up the image and I like the ''dirty'' clock face. Looking at it more it looks like a clock instead of my initial thought of a pocketwatch, which explains the ''column'' at the back that seemed a little distracting.', '2004-03-11 11:38:03.000000', NULL, 1),
(618022, 63431, 6008, '<td valign="top">Good use of filling the frame with the subject and yet still making it easily recognisable. I also like the second plane in the background to give it more depth. The black and white has good contrasts and works for this image.</td>', 'Good use of filling the frame with the subject and yet still making it easily recognisable. I also like the second plane in the background to give it more depth. The black and white has good contrasts and works for this image.', '2004-03-11 11:40:21.000000', NULL, 1),
(618033, 63580, 6008, '<td valign="top">I admit that without the title this probably wouldnt be as neat an image as it is with it. I love the dark black and white, the contrasts are great. The angle compliments the title by making me think of a final turn made by a plane. The sparkly bits really add that ''ting'' to the shot too, and it does indeed look like a city. I''m not one for circuit bord shots, but I do like this one as it has interest.</td>', 'I admit that without the title this probably wouldnt be as neat an image as it is with it. I love the dark black and white, the contrasts are great. The angle compliments the title by making me think of a final turn made by a plane. The sparkly bits really add that ''ting'' to the shot too, and it does indeed look like a city. I''m not one for circuit bord shots, but I do like this one as it has interest.', '2004-03-11 11:44:38.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(618038, 63495, 6008, '<td valign="top">Interesting building and a good shot. There appears, however, to be something missing. I''m not sure what it is, and I dont really see anything bad about it, but it just doesnt have that ''wow'' factor. It''s a good shot of a good building, but it doesnt seem to grab my attention. If you know what I mean!</td>', 'Interesting building and a good shot. There appears, however, to be something missing. I''m not sure what it is, and I dont really see anything bad about it, but it just doesnt have that ''wow'' factor. It''s a good shot of a good building, but it doesnt seem to grab my attention. If you know what I mean!', '2004-03-11 11:47:28.000000', NULL, 1),
