(618520, 63371, 6888, '<td valign="top">Nice take on the challenge, composition is nice, colors are good &amp; bright</td>', 'Nice take on the challenge, composition is nice, colors are good & bright', '2004-03-11 19:58:27.000000', NULL, 1),
(618521, 63547, 6888, '<td valign="top">One of the better watch shots this challenge, it is all in good focus, the cropping is good and the b/w works well</td>', 'One of the better watch shots this challenge, it is all in good focus, the cropping is good and the b/w works well', '2004-03-11 19:59:12.000000', NULL, 1),
