(619375, 63615, 18411, '<td valign="top">I love this one, The colors and lines are great!</td>', 'I love this one, The colors and lines are great!', '2004-03-12 17:22:04.000000', NULL, 1),
(619390, 63609, 8610, '<td valign="top">I have moved a lot closer, I can see you shot this with widelens,, moved lot closer and rid of the sign</td>', 'I have moved a lot closer, I can see you shot this with widelens,, moved lot closer and rid of the sign', '2004-03-12 17:43:04.000000', NULL, 1),
(619393, 63431, 3697, '<td valign="top">Absolutely great composition, and the black and white toning is awesome. This fits this week''s theme very nicely.</td>', 'Absolutely great composition, and the black and white toning is awesome. This fits this week''s theme very nicely.', '2004-03-12 17:43:22.000000', NULL, 1),
(619400, 63138, 3697, '<td valign="top">What an interesting structure, what exactly is it? Fit''s this week''s theme very well IMO.</td>', 'What an interesting structure, what exactly is it? Fit''s this week''s theme very well IMO.', '2004-03-12 17:46:42.000000', NULL, 1),
(619413, 63605, 6624, '<td valign="top">basics indeed and well done - the high lighting over-exposed effect works well here</td>', 'basics indeed and well done - the high lighting over-exposed effect works well here', '2004-03-12 18:22:39.000000', NULL, 1),
(619425, 63213, 15207, '<td valign="top">Awesome shot. I really like the DOF here and the fact that the way you composed the image draws you in - the lines really help to move your eye. I like the lighting as well. Good luck!</td>', 'Awesome shot. I really like the DOF here and the fact that the way you composed the image draws you in - the lines really help to move your eye. I like the lighting as well. Good luck!', '2004-03-12 18:38:25.000000', NULL, 1),
(619426, 63715, 15207, '<td valign="top">I just love the colour contrast in this one. Great idea for this challenge. Good luck!</td>', 'I just love the colour contrast in this one. Great idea for this challenge. Good luck!', '2004-03-12 18:38:56.000000', NULL, 1),
(619427, 63456, 15207, '<td valign="top">I really like this shot. It reminds me of Vancouver - I''ll be interested to read where you shot it. I really like the contrast between the square windows in the office building and the circular balconies. - score 9</td>', 'I really like this shot. It reminds me of Vancouver - I''ll be interested to read where you shot it. I really like the contrast between the square windows in the office building and the circular balconies. - score 9', '2004-03-12 18:39:53.000000', NULL, 1),
(619430, 63142, 15207, '<td valign="top">This is a really beautiful shot. I really like the darkness and the lighting. It''s a well balanced shot with great composition.</td>', 'This is a really beautiful shot. I really like the darkness and the lighting. It''s a well balanced shot with great composition.', '2004-03-12 18:43:40.000000', NULL, 1),
(619431, 63422, 15207, '<td valign="top">Very cool shot. This looks like something out of an architectural digest page. I really like the composition and the colours/</td>', 'Very cool shot. This looks like something out of an architectural digest page. I really like the composition and the colours/', '2004-03-12 18:44:19.000000', NULL, 1),
(619432, 63546, 12661, '<td valign="top">Good think I looked it up before commenting. I was going to say that the plane is an SR-71 but just learned that there is in fact an M-21. Anyway, I like the POV, however, I would have tried to include the entire engine since that is where the magnificence of the blackbird lies.</td>', 'Good think I looked it up before commenting. I was going to say that the plane is an SR-71 but just learned that there is in fact an M-21. Anyway, I like the POV, however, I would have tried to include the entire engine since that is where the magnificence of the blackbird lies.', '2004-03-12 18:44:21.000000', NULL, 1),
(619433, 63579, 15207, '<td valign="top">This looks like such a hard shot to compose. I gave it a 10. I really like the balance - literally, artistically and metaphorically. Good luck!</td>', 'This looks like such a hard shot to compose. I gave it a 10. I really like the balance - literally, artistically and metaphorically. Good luck!', '2004-03-12 18:45:03.000000', NULL, 1),
(619459, 63139, 2158, '<td valign="top">I love the effect of the curves here, but personally find the black on the right hand side a bit much.  My preference would be to crop it to a 4:3 ratio.</td>', 'I love the effect of the curves here, but personally find the black on the right hand side a bit much.  My preference would be to crop it to a 4:3 ratio.', '2004-03-12 19:21:52.000000', NULL, 1),
(619499, 63139, 12160, '<td valign="top"></td>', '', '2004-03-12 20:06:21.000000', NULL, 1),
(619504, 63599, 12160, '<td valign="top">Very nice image. It''s a challenge to balance the exposure in this kind of lighting but you managed it well. 9</td>', 'Very nice image. It''s a challenge to balance the exposure in this kind of lighting but you managed it well. 9', '2004-03-12 20:09:03.000000', NULL, 1),
(619505, 63378, 12160, '<td valign="top">Simple and effective. well done. 9</td>', 'Simple and effective. well done. 9', '2004-03-12 20:10:08.000000', NULL, 1),
(619512, 63609, 12160, '<td valign="top">Fits the challenge well. Good use of a wide angle lens and the car near the door of the church gave size perspective to the subject. The metal post, to me would have been better cropped off as it doesn''t add anything to the photo (unless the sign has some significance that I don''t understand).  The tower is also crooked which could have been fixed in image editor. 7</td>', 'Fits the challenge well. Good use of a wide angle lens and the car near the door of the church gave size perspective to the subject. The metal post, to me would have been better cropped off as it doesn''t add anything to the photo (unless the sign has some significance that I don''t understand).  The tower is also crooked which could have been fixed in image editor. 7', '2004-03-12 20:18:24.000000', NULL, 1),
(619522, 63213, 12160, '<td valign="top">Nice shot, good use of shallow dof. 8</td>', 'Nice shot, good use of shallow dof. 8', '2004-03-12 20:41:08.000000', NULL, 1),
(619523, 63435, 12160, '<td valign="top">excellent image. 10</td>', 'excellent image. 10', '2004-03-12 20:42:15.000000', NULL, 1),
(619530, 63579, 12475, '<td valign="top">Great shot: simple, nice tones, beautifully composed.</td>', 'Great shot: simple, nice tones, beautifully composed.', '2004-03-12 20:52:10.000000', NULL, 1),
(619578, 63432, 10785, '<td valign="top">An atypical view to be sure. But, aside from the title, I can barely recognize this icon of Missouri. I believe even though one takes a different perspepctive of an object, it should still be recognizable.</td>', 'An atypical view to be sure. But, aside from the title, I can barely recognize this icon of Missouri. I believe even though one takes a different perspepctive of an object, it should still be recognizable.', '2004-03-12 23:46:29.000000', NULL, 1),
(619579, 63615, 10785, '<td valign="top">My pick for a Blue!</td>', 'My pick for a Blue!', '2004-03-12 23:49:11.000000', NULL, 1),
(619582, 63603, 10785, '<td valign="top">good shot but the thick black edge is distracting.</td>', 'good shot but the thick black edge is distracting.', '2004-03-12 23:59:14.000000', NULL, 1),
(619584, 63546, 10785, '<td valign="top">Isn''t the Blackbird the SR-71? No matter...great shot!</td>', 'Isn''t the Blackbird the SR-71? No matter...great shot!', '2004-03-13 00:06:21.000000', NULL, 1),
(619595, 63632, 6870, '<td valign="top">This is a clever idea. It reminds me of a chip in Data''s head on Star Trek. It seems a bit unclear, though. I love the little wires coming out from it, and the colors are intriguing.</td>', 'This is a clever idea. It reminds me of a chip in Data''s head on Star Trek. It seems a bit unclear, though. I love the little wires coming out from it, and the colors are intriguing.', '2004-03-13 00:24:36.000000', NULL, 1),
(619596, 63142, 6870, '<td valign="top">Nice reflection shot with the interesting curve of the concrete to lead my eye in. I''m not sure the letters are important enough to include, though. It says plenty just with the reflection, but I can see the connection, so I''m kind of up in the air with that. The bright spot at the bottom probably gets too much attention. I like how the reflection is cut up in to many fragements.</td>', 'Nice reflection shot with the interesting curve of the concrete to lead my eye in. I''m not sure the letters are important enough to include, though. It says plenty just with the reflection, but I can see the connection, so I''m kind of up in the air with that. The bright spot at the bottom probably gets too much attention. I like how the reflection is cut up in to many fragements.', '2004-03-13 00:26:55.000000', NULL, 1),
(619763, 63336, 14603, '<td valign="top">Nice idea and good composition.</td>', 'Nice idea and good composition.', '2004-03-13 06:35:01.000000', NULL, 1),
(619764, 63588, 14603, '<td valign="top">Very intriguing image, I would like to have seen a figure or some sort of recognisable feature in the picture somewhere to give me an idea of scale.<br/>Good composition and lighting</td>', 'Very intriguing image, I would like to have seen a figure or some sort of recognisable feature in the picture somewhere to give me an idea of scale.Good composition and lighting', '2004-03-13 06:42:38.000000', NULL, 1),
(619766, 63675, 14603, '<td valign="top">Well thought out and perfect for the challenge.<br/>If the nearest digger had been eliminated from the picture and the image cropped to include just  blue sky and cloud in the top third....this would have been my favourite from the challenge.<br/>of course this is only my personal feel for the image and the majority may prefer it the way it is.<br/>Good work</td>', 'Well thought out and perfect for the challenge.If the nearest digger had been eliminated from the picture and the image cropped to include just  blue sky and cloud in the top third....this would have been my favourite from the challenge.of course this is only my personal feel for the image and the majority may prefer it the way it is.Good work', '2004-03-13 06:54:49.000000', NULL, 1),
