(620424, 63716, 3306, '<td valign="top">Interesting pattern and DOF.</td>', 'Interesting pattern and DOF.', '2004-03-14 06:33:17.000000', NULL, 1),
(620425, 63587, 3306, '<td valign="top">This is an interesting subject but you have taken the picture at an uninteresting angle. If you took it from above or below it would haved given the viewer a perspective that one does not usually get. Also, it would have made the pole more central to the picture and removed alot of the distractions in the backround.</td>', 'This is an interesting subject but you have taken the picture at an uninteresting angle. If you took it from above or below it would haved given the viewer a perspective that one does not usually get. Also, it would have made the pole more central to the picture and removed alot of the distractions in the backround.', '2004-03-14 06:36:12.000000', NULL, 1),
(620426, 63234, 3306, '<td valign="top">Simple and too the point.</td>', 'Simple and too the point.', '2004-03-14 06:36:42.000000', NULL, 1),
